    """自由班制下工作日不打卡是否记为缺卡"""
    remedy_period_type: int | None = None
    """补卡周期类型。1为按自然月，2为自定义周期 * 1：MONTH * 2：CUSTOM"""
    remedy_period_custom_date: int | None = None
    """补卡自定义周期起始日期"""
    punch_type: int | None = None
    """打卡类型，位运算。1：GPS 打卡，2：Wi-Fi 打卡，4：考勤机打卡，8：IP 打卡"""
    effect_time: str | None = None
    """生效时间，精确到秒的时间戳"""
    fixshift_effect_time: str | None = None
    """固定班次生效时间，精确到秒的时间戳"""
    member_effect_time: str | None = None
    """参加考勤的人员、部门变动生效时间，精确到秒的时间戳"""
    rest_clockIn_need_approval: bool | None = None
    """休息日打卡需审批"""
    clockIn_need_photo: bool | None = None
    """每次打卡均需拍照"""
    member_status_change: MemberStatusChange | None = None
    """人员异动打卡设置"""
    leave_need_punch: bool | None = None
    """请假离岗或返岗是否需打卡"""
    leave_need_punch_cfg: LeaveNeedPunchCfg | None = None
    """请假离岗或返岗打卡规则，单位：分钟"""
    go_out_need_punch: int | None = None
    """外出期间是否需打卡"""
    go_out_need_punch_cfg: LeaveNeedPunchCfg | None = None
    """外出期间打卡规则，单位：分钟"""
    travel_need_punch: int | None = None
    """出差期间是否需打卡"""
    travel_need_punch_cfg: LeaveNeedPunchCfg | None = None
    """出差期间打卡规则，单位：分钟"""
    need_punch_members: list[PunchMember] | None = None
    """需要打卡的人员集合（当「bind_dept_ids」和「bind_user_ids」不为空时，以「bind_dept_ids」和「bind_user_ids」为准）"""
    no_need_punch_members: list[PunchMember] | None = None
    """无需打卡的人员集合（当「bind_default_dept_ids」和「bind_default_user_ids」不为空时，以「bind_default_dept_ids」和「bind_default_user_ids」为准）"""
    save_auto_changes: bool | None = None
