    bind_default_user_ids: list[str] | None = None
    """参与无需打卡的人员 ID 列表（与「no_need_punch_members」同时使用时，以当前字段为准）。对应employee_type"""
    overtime_clock_cfg: OvertimeClockCfg | None = None
    """加班打卡规则"""
    new_calendar_id: str | None = None
